const stamp = (value: Date | string | null | undefined) => value ? new Date(value).toLocaleString("de-DE", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }) : "–";
const startedLabel = (value: Date | string) => new Date(value).toLocaleString("de-DE", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }) + " Uhr";
const statusLabel: Record<string, string> = { entwurf: "Entwurf", aktiv: "Aktiv", pausiert: "Pausiert", beendet: "Beendet" };
/** Reihenfolge der Kampagnen-Übersicht – A–Z ist Standard; die Wahl bleibt im Browser gespeichert. */
type CampaignSort = "az" | "za" | "bearbeitet" | "erstellt" | "gestartet" | "status";
const SORT_OPTIONS: Array<[CampaignSort, string]> = [["az", "Name A–Z"], ["za", "Name Z–A"], ["bearbeitet", "Zuletzt bearbeitet"], ["erstellt", "Zuletzt angelegt"], ["gestartet", "Zuletzt gestartet"], ["status", "Status: Aktiv zuerst"]];
const STATUS_ORDER: Record<string, number> = { aktiv: 0, pausiert: 1, entwurf: 2, beendet: 3 };
const readSort = (): CampaignSort => { try { const saved = localStorage.getItem("kampagnen-sortierung"); return SORT_OPTIONS.some(([key]) => key === saved) ? (saved as CampaignSort) : "az"; } catch { return "az"; } };
function sortCampaigns<T extends { name: string; status: string; updatedAt: Date | string; createdAt?: Date | string | null; startedAt: Date | string | null }>(rows: T[], sort: CampaignSort): T[] {
  const time = (value: Date | string | null | undefined) => value ? new Date(value).getTime() : 0;
  return [...rows].sort((a, b) => { const name = a.name.localeCompare(b.name, "de", { sensitivity: "base", numeric: true });
    if (sort === "za") return -name; if (sort === "bearbeitet") return time(b.updatedAt) - time(a.updatedAt) || name; if (sort === "erstellt") return time(b.createdAt) - time(a.createdAt) || name;
    if (sort === "gestartet") return time(b.startedAt) - time(a.startedAt) || name; if (sort === "status") return (STATUS_ORDER[a.status] ?? 9) - (STATUS_ORDER[b.status] ?? 9) || name; return name; });
}
const recipientLabel: Record<string, string> = { wartet: "Wartet", laeuft: "Läuft", fertig: "Fertig", fehler: "Fehler", abgemeldet: "Abgemeldet", bounce: "Unzustellbar", beschwerde: "Beschwerde" };
const eventLabel: Record<string, string> = { gesendet: "Gesendet", geoeffnet: "Geöffnet", geklickt: "Geklickt", gewartet: "Wartet", verzweigt: "Verzweigt", beendet: "Beendet", abgemeldet: "Abgemeldet", bounce: "Unzustellbar", beschwerde: "Beschwerde", fehler: "Fehler" };
